import{describe,it,expect}from"vitest";import{AWARD_ENCYCLOPEDIA,filterAwardsByCategory,searchAwardsAndRecipients,getAwardDetailsByKey}from"../../frontend/js-modules/national-awards.js";describe("National Awards Encyclopedia Dataset Completeness",()=>{it("contains entries for all required Civilian, Gallantry, Sports, and Literature awards",()=>{const e=Object.keys(AWARD_ENCYCLOPEDIA);expect(e).toContain("bharat-ratna"),expect(e).toContain("padma-vibhushan"),expect(e).toContain("padma-bhushan"),expect(e).toContain("padma-shri"),expect(e).toContain("vishisht-seva-medal"),expect(e).toContain("ati-vishisht-seva-medal"),expect(e).toContain("presidents-police-medal"),expect(e).toContain("param-vir-chakra"),expect(e).toContain("maha-vir-chakra"),expect(e).toContain("vir-chakra"),expect(e).toContain("ashoka-chakra"),expect(e).toContain("kirti-chakra"),expect(e).toContain("shaurya-chakra"),expect(e).toContain("khel-ratna"),expect(e).toContain("arjuna-award"),expect(e).toContain("dronacharya-award"),expect(e).toContain("jnanpith-award"),expect(e).toContain("sahitya-akademi-award"),expect(e).toContain("national-bravery-awards"),expect(e).toContain("pradhan-mantri-rashtriya-bal-puraskar")}),it("every award entry contains all 5 required sections (Eligibility, History, Medal design, Winners, Interesting facts)",()=>{Object.values(AWARD_ENCYCLOPEDIA).forEach(e=>{expect(e,`Award ${e.name} missing id`).toHaveProperty("id"),expect(e,`Award ${e.name} missing name`).toHaveProperty("name"),expect(e,`Award ${e.name} missing category`).toHaveProperty("category"),expect(e,`Award ${e.name} missing eligibility`).toHaveProperty("eligibility"),expect(e,`Award ${e.name} missing history`).toHaveProperty("history"),expect(e,`Award ${e.name} missing medalDesign`).toHaveProperty("medalDesign"),expect(e,`Award ${e.name} missing notableWinners`).toHaveProperty("notableWinners"),expect(e,`Award ${e.name} missing interestingFacts`).toHaveProperty("interestingFacts"),expect(e.eligibility.trim().length).toBeGreaterThan(15),expect(e.history.trim().length).toBeGreaterThan(15),expect(e.medalDesign.trim().length).toBeGreaterThan(15),expect(Array.isArray(e.notableWinners)).toBe(!0),expect(e.notableWinners.length).toBeGreaterThan(0),expect(Array.isArray(e.interestingFacts)).toBe(!0),expect(e.interestingFacts.length).toBeGreaterThan(0)})}),it("maintains non-partisan, neutral, and educational tone",()=>{const e=["corrupt","worthless","scam","fraudulent"];Object.values(AWARD_ENCYCLOPEDIA).forEach(t=>{const a=`${t.name} ${t.eligibility} ${t.history} ${t.medalDesign}`.toLowerCase();e.forEach(e=>{expect(a).not.toContain(e)})})})}),describe("National Awards Helper & Filter Logic",()=>{it("filters awards correctly by category",()=>{const e=filterAwardsByCategory("civilian");expect(e.length).toBe(4),e.forEach(e=>expect(e.category).toBe("civilian"));const t=filterAwardsByCategory("gallantry");expect(t.length).toBe(6),t.forEach(e=>expect(e.category).toBe("gallantry"));const a=filterAwardsByCategory("sports");expect(a.length).toBe(3),a.forEach(e=>expect(e.category).toBe("sports"));const r=filterAwardsByCategory("literature");expect(r.length).toBe(2),r.forEach(e=>expect(e.category).toBe("literature"))}),it("searches awards and recipient names accurately",()=>{const e=searchAwardsAndRecipients("Param Vir Chakra");expect(e.length).toBeGreaterThanOrEqual(1),expect(e[0].id).toBe("param-vir-chakra");const t=searchAwardsAndRecipients("Vikram Batra");expect(t.length).toBeGreaterThanOrEqual(1),expect(t[0].id).toBe("param-vir-chakra");const a=searchAwardsAndRecipients("Jnanpith");expect(a.length).toBeGreaterThanOrEqual(1),expect(a[0].id).toBe("jnanpith-award")}),it("retrieves single award details by key correctly",()=>{const e=getAwardDetailsByKey("bharat-ratna");expect(e).not.toBeNull(),expect(e.name).toBe("Bharat Ratna");const t=getAwardDetailsByKey("unknown-award");expect(t).toBeNull()})});